package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenFractionDecimalPercentRecallScopeTest {
 private static final String SYSTEM="na-nied-primary-2024-v1",ID=FractionDecimalPercentRecall.ID;
 private static Question q(String n,String d){return new Question(ID,FractionDecimalPercentRecall.prompt(n,d),"-999.123456789","999","999");}
 @Test public void NormalNaSevenRecallBalancesFamiliarGroupsAndExhaustsAllTwoHundredTwentyFourOriginals(){
  var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(SYSTEM)).findFirst().orElseThrow();assertTrue(pack.inGrade(ID,7));assertFalse(pack.inGrade(ID,6));assertEquals(1,Catalog.ALL.stream().filter(s->s.id.equals(ID)).count());assertEquals("분수·소수·백분율 대응값",Catalog.get(ID).title);CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,ID,7);
  for(boolean mc:List.of(false,true)){Generator gen=new Generator(new Random(363));List<String> recent=new ArrayList<>();Set<Integer> denominators=new HashSet<>(),firstGroups=new HashSet<>(),fifths=new HashSet<>();boolean zero=false,one=false,threeQuarters=false,unreduced=false;
   for(int i=0;i<224;i++){Question q=gen.next(ID,recent,mc,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var g=FractionDecimalPercentRecall.read(q);assertNotNull(g);int n=g.numerator().intValueExact(),d=g.denominator().intValueExact();assertTrue(FractionDecimalPercentRecall.SELECTED_DENOMINATORS.contains(d)&&n>=0&&n<=d);denominators.add(d);if(d==5)fifths.add(n);if(i<3)firstGroups.add(d==2||d==4?0:d==5?1:2);zero|=g.value().isZero();one|=g.value().equals(Rational.ONE);threeQuarters|=n==3&&d==4;unreduced|=n>0&&!g.numerator().gcd(g.denominator()).equals(BigInteger.ONE);assertTrue(limits.allows(q));assertEquals(ID,q.kind);assertEquals(ID,q.answerFormat);assertArrayEquals(new String[]{"소수 값","백분율 (%)"},q.labels);assertEquals(2,q.answers.length);assertTrue(q.choices.isEmpty());assertTrue(q.choiceLabels.isEmpty());assertEquals(-1,q.correctChoice);assertFalse(FractionInput.available(q));assertFalse(FractionInput.defaultFraction(q));assertFalse(q.stepSupport);assertEquals(4,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());assertTrue(new Checker().check(q,List.of(),Arrays.asList(q.answers)).correct());}
   assertEquals(FractionDecimalPercentRecall.SELECTED_DENOMINATORS,denominators);assertEquals(Set.of(0,1,2),firstGroups);assertEquals(Set.of(0,1,2,3,4,5),fifths);assertTrue(zero&&one&&threeQuarters&&unreduced);assertEquals(recent.get(0),gen.next(ID,recent,mc,limits).signature());
  }
  Question created=new Generator(new Random(363)).create(Catalog.get(ID));assertNotNull(FractionDecimalPercentRecall.read(created));assertEquals(2,created.answers.length);assertEquals(ID,created.kind);
 }
 @Test public void DeclaredSourceAndBothResultFiltersIgnorePrivateMetadataAndDoNotBoundGeneralRecall(){
  Question q=q("1","4");q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;CurriculumLimits selected=GlobalCurriculum.limits(SYSTEM,ID,7);assertTrue(selected.allows(q));q.expression=null;q.answers=null;assertTrue(selected.allows(q));assertTrue(new CurriculumLimits("maxGiven=4;minGiven=0;denominators=4;maxResult=25").allows(q));assertFalse(new CurriculumLimits("maxGiven=3").allows(q));assertFalse(new CurriculumLimits("minGiven=2").allows(q));assertFalse(new CurriculumLimits("maxResult=24").allows(q));assertFalse(new CurriculumLimits("denominators=5").allows(q));assertTrue(new CurriculumLimits("percentages=25").allows(q));assertFalse(new CurriculumLimits("percentages=20").allows(q));assertTrue(new CurriculumLimits("unitFractions=true").allows(q));assertTrue(new CurriculumLimits("answerDecimalPlaces=2").allows(q));assertFalse(new CurriculumLimits("answerDecimalPlaces=1").allows(q));assertFalse(new CurriculumLimits("answerDomain=integer").allows(q));assertSame(stored,q.studyGuide);assertNull(q.expression);assertNull(q.answers);
  Question third=q("1","3"),improper=q("3","2");assertFalse(selected.allows(third));assertFalse(selected.allows(improper));assertTrue(CurriculumLimits.NONE.allows(third));assertTrue(CurriculumLimits.NONE.allows(improper));assertTrue(new CurriculumLimits("decimalPlaces=1").allows(third));assertFalse(new CurriculumLimits("answerDecimalPlaces=3").allows(third));assertTrue(new Checker().check(third,List.of(),List.of("0.(3)","33.(3)")).correct());assertTrue(new Checker().check(improper,List.of(),List.of("1.5","150")).correct());Question outside=q("1","8");assertFalse(selected.allows(outside));assertTrue(CurriculumLimits.NONE.allows(outside));assertTrue(new Checker().check(outside,List.of(),List.of("0.125","12.5")).correct());Question huge=q("99999999999999999999","1");assertFalse(selected.allows(huge));assertTrue(CurriculumLimits.NONE.allows(huge));
 }
 @Test public void ExistingNumericPercentageConversionRecallRoundedAndTypedSymbolContractsRemainSeparate(){
  Question legacy=FractionPercentEquivalence.make(3,4);assertArrayEquals(new String[]{"소수 값","백분율 (%)"},legacy.labels);assertTrue(new Checker().check(legacy,List.of(),List.of("0.75","75")).correct());assertFalse(new Checker().check(legacy,List.of(),List.of("0.75","75%")).correct());assertEquals(5,HelpPlan.forQuestion(legacy).size());assertEquals("fraction-percent-equivalence-v1",HelpPlan.forQuestion(legacy).restore(null,legacy.id).teachingVersion);assertFalse(HelpPlan.forQuestion(legacy).canTransfer());Question hundredths=PercentageNotation.make(PercentageNotation.FRACTION,35);assertTrue(new Checker().check(hundredths,List.of(),List.of("35/100")).correct());assertFalse(new Checker().check(hundredths,List.of(),List.of("7/20")).correct());assertEquals(3,HelpPlan.forQuestion(hundredths).size());
  Question recall=new Question(FractionDecimalRecall.ID,FractionDecimalRecall.prompt("1","1"),"poison","999");assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(recall,List.of(),List.of("1")).status);assertTrue(new Checker().check(q("1","1"),List.of(),List.of("1","100")).correct());Question rounded=new Question(FractionToDecimalCheck.ID,FractionDecimalDivision.prompt("1","3"),"poison","999");assertTrue(new Checker().check(rounded,List.of(),List.of("0.333")).correct());assertEquals(23,HelpPlan.forQuestion(rounded).size());Question reduced=DecimalToFractionSupply.makeReduced(0,45,2);assertTrue(new Checker().check(reduced,List.of(),List.of("9/20")).correct());assertEquals(7,HelpPlan.forQuestion(reduced).size());assertEquals(2,GlobalCurriculum.limits(SYSTEM,DecimalToFractionSupply.ID,6).decimalPlaces(1));Question meaning=PercentageMeaning.make(35);assertTrue(new Checker().check(meaning,List.of(),List.of("100","35%")).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(meaning,List.of(),List.of("100","35")).status);
  Question conversion=new Question(RepresentationConversions.FP,RepresentationConversions.prompt(RepresentationConversions.FP,"1/5"),"poison","999");assertTrue(new Checker().check(conversion,List.of(),List.of("20%")).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(conversion,List.of(),List.of("20")).status);assertEquals(5,HelpPlan.forQuestion(conversion).size());
 }
}
